#include <bits/stdc++.h>
using namespace std;
#define int long long

int f(vector<int>& arr, int n, int a , int b) {
    int sum_six = 6 * (arr[a] - arr[0]);
    int sum_four = 4 * (arr[a+2*b] - arr[a]);
    int sum_three = 3 * (arr[3*n-2 * a - b] - arr[a+2*b]);
    
    return sum_six + sum_four + sum_three;
}

signed main() {
	// your code goes here

    int t;
    cin >> t;
    
    for(int i=0; i<t; i++) {
        int n;
        cin >> n;
        
        vector<int> vec(n*3);
        for(int i=0; i<n*3; i++) {
            cin >> vec[i];
        }
        
        sort(vec.rbegin(), vec.rend());
        
        vector<int> a(n*3+1, 0);
        
        for(int i=0; i<3*n; i++) {
            a[i+1] = a[i] + vec[i];
        }
        
        int ans = 0;
        
        for(int i=0; i<=n; i++) {
            int low = 0, high = n-i;
            int best_b = low;
            int mid;
            while(low<=high) {
                mid = low + (high - low) / 2;
                int score_mid = f(a, n, i, mid);
                
                int score_next = (mid + 1 <= n-i) ? f(a, n, i, mid+1) : -1; 
                
                if(score_next > score_mid) low = mid + 1;
                else  {
                    best_b = mid;
                    high = mid - 1;
                }
            }
            
            ans = max(ans, f(a, n, i, best_b));
        }
        
        cout << ans << endl;
    }
}
